import { _decorator, Color, Component, Graphics, Node } from 'cc';
import type { EntityView } from '../../Engine/ViewRegistry';
import type { Entity } from '../../Engine/Entity';
import type { Boss } from '../Entity/Boss';
const { ccclass} = _decorator;

@ccclass('BossView')
export class BossView extends Component implements EntityView{

    private _boss: Boss| null = null;

    private _turretNodes: Node[] = [];

    onLoad() {
        const g = this.node.addComponent(Graphics);
        g.fillColor = new Color(220, 60, 60, 255);
        // 先画个占位方块，大小按 collisionRadius 后续可调
        g.rect(-50, -50, 100, 100);
        g.fill();
    }

    bind(entity: Entity): void {
        this._boss = entity as Boss;
        this._createTurretNodes();
        this.sync(0);
    }

    private _createTurretNodes(): void {
        if (!this._boss) return;

        for (let i = 0; i < this._boss.turrets.length; i++) {
            const node = new Node(`turret_${i}`);
            node.parent = this.node;

            const g = node.addComponent(Graphics);
            // 炮台底座：深色圆
            g.fillColor = new Color(180, 40, 40, 255);
            g.circle(0, 0, 14);
            g.fill();
            // 枪管：从中心向前伸出的线段（默认朝 Cocos 的 0°，即上方）
            g.strokeColor = new Color(255, 200, 100, 255);
            g.lineWidth = 4;
            g.moveTo(0, 0);
            g.lineTo(0, 24);
            g.stroke();

            this._turretNodes.push(node);
        }
    }

    sync(dt: number): void {
        if(!this._boss){return;}
        this.node.setPosition(this._boss.x,this._boss.y);

        for (let i = 0; i < this._boss.turrets.length; i++) {
            const turret = this._boss.turrets[i];
            const node = this._turretNodes[i];
            if (!node) continue;

            node.setPosition(turret.config.offsetX, turret.config.offsetY);
            node.angle = this._toCocosAngle(turret.aimAngle);
        }
    }   

    /**
     * 数学角度 → Cocos node.angle。
     * 数学：0° = 右，90° = 上（Math.atan2 的约定）
     * Cocos：0° = 上，正角度顺时针
     * 转换：cocosAngle = 90 - mathAngle
     */
    private _toCocosAngle(mathAngle: number): number {
        return mathAngle - 90;
    }

    unbind(): void {
        for (let i = 0; i < this._turretNodes.length; i++) {
            this._turretNodes[i].destroy();
        }
        this._turretNodes.length = 0;
        this._boss = null;
    }
}


